program.compute:
options = read('/input/options')
existing = read('/output/selection')
result = existing
if existing is None:
    result = None
    for count in range(goal['min_count'], goal['max_count'] + 1):
        for group in combinations(options, count):
            proposal = [row['id'] for row in group]
            if valid(proposal):
                result = proposal
                break
        if result is not None:
            break

program.effects:
if result is None:
    status('report')
else:
    if existing is None:
        write('/output/selection', result)
    delivery = receipt('report')
    if delivery == 'success':
        pass
    elif delivery == 'unknown':
        status('report')
    elif delivery == 'unattempted':
        send('report', 'team', result)
    elif delivery == 'failure':
        status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')

